document.addEventListener("DOMContentLoaded",(()=>{"use strict";class UbuntuDevSpace{constructor(config={}){this.config={dataUrl:"https://cdn.jsdelivr.net/gh/OumaNyang/ubuntu-devspace-js@main/data/clients.data.json",noticeDisplayDays:30,...config};this.html=document.documentElement;this.body=document.body;this.currentDomain=window.location.hostname;this.notices=this.createNoticeTemplates()}createNoticeTemplates(){return{development:{title:"Exciting Changes Coming Soon!",message:"We're currently working behind the scenes to bring you a more robust, interactive, and modern website experience.",color:"#4a6fa5",icon:"🚀",gradient:"linear-gradient(135deg, #e6f0ff 0%, #c9e2ff 100%)",contactLabel:"For inquiries, please contact:"},maintenance:{title:"Maintenance Ongoing",message:"We're performing important updates to improve your experience. Thank you for your patience!",color:"#5a8f69",icon:"🔧",gradient:"linear-gradient(135deg, #f0fff4 0%, #d1ffe1 100%)",contactLabel:"Need immediate assistance?"},administrative_hold:{title:"Administrative Hold",message:"This website is temporarily unavailable due to administrative review.",color:"#b35900",icon:"⏸️",gradient:"linear-gradient(135deg, #fff4e6 0%, #ffe0b3 100%)",contactLabel:"For status inquiries:"},suspended:{title:"License Suspended",message:"This website is currently unavailable due to license suspension.",color:"#a04a4a",icon:"⛔",gradient:"linear-gradient(135deg, #fff0f0 0%, #ffd1d1 100%)",contactLabel:"For reinstatement:"},expired:{title:"License Expired",message:"This website is unavailable because the development license has expired.",color:"#8e44ad",icon:"⌛",gradient:"linear-gradient(135deg, #f5eef8 0%, #e8daef 100%)",contactLabel:"To renew your license:"},legal_hold:{title:"Legal Restriction",message:"This website is temporarily unavailable due to legal proceedings.",color:"#6a4a8f",icon:"⚖️",gradient:"linear-gradient(135deg, #f5f0ff 0%, #e2d1ff 100%)",contactLabel:"Legal inquiries:"},compliance_hold:{title:"Compliance Review",message:"This website is temporarily unavailable during compliance verification.",color:"#2980b9",icon:"🔍",gradient:"linear-gradient(135deg, #eaf2f8 0%, #d4e6f1 100%)",contactLabel:"For compliance questions:"},deleted:{title:"Service Terminated",message:"This website is no longer available.",color:"#5a5a5a",icon:"❌",gradient:"linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%)",contactLabel:""}}}async fetchClientData(){try{const response=await fetch(this.config.dataUrl);if(!response.ok)throw new Error(`HTTP error! status: ${response.status}`);return await response.json()}catch(error){console.error("Failed to load client data:",error);return null}}async handleLicenseStatus(){const devData=await this.fetchClientData();if(!devData)return;const domainData=devData[this.currentDomain];if(!domainData){this.displayNotice("deleted");return}const status=domainData.dev_licence_status;const validStatuses=Object.keys(this.notices);if(validStatuses.includes(status)){if(status==="deleted"){this.displayBlankPage()}else if(status==="active"){}else{this.displayNotice(status,domainData)}}else{this.displayNotice("suspended",domainData)}}displayNotice(type,domainData=null){const notice=this.notices[type]||this.notices.suspended;const clientEmail=domainData?.customer_email||domainData?.client_email||"info@example.com";const clientName=domainData?.client_name||"the website owner";const clientPhone=domainData?.customer_phone?`<p>Phone: ${domainData.customer_phone}</p>`:"";const noticeHTML=`\n              <style>\n                  .license-notice-container {\n                      margin: 0;\n                      padding: 0;\n                      background: ${notice.gradient};\n                      font-family: 'Ubuntu', 'Segoe UI', Roboto, sans-serif;\n                      display: flex;\n                      justify-content: center;\n                      align-items: center;\n                      min-height: 100vh;\n                      color: #333;\n                      line-height: 1.5;\n                  }\n                  \n                  .license-notice {\n                      background: white;\n                      width: calc(100% - 40px);\n                      max-width: 500px;\n                      border-radius: 12px;\n                      box-shadow: 0 5px 15px rgba(0,0,0,0.08);\n                      padding: 1.5rem;\n                      margin: 20px;\n                      text-align: center;\n                      animation: fadeIn 0.4s ease-out;\n                      border: 1px solid rgba(0,0,0,0.05);\n                  }\n                  \n                  .notice-title {\n                      color: ${notice.color};\n                      font-weight: 700;\n                      font-size: 1.4rem;\n                      margin-bottom: 1rem;\n                      display: flex;\n                      align-items: center;\n                      justify-content: center;\n                      gap: 0.5rem;\n                  }\n                  \n                  .notice-content {\n                      color: #444;\n                      font-size: 1rem;\n                      margin-bottom: 1rem;\n                  }\n                  \n                  .divider {\n                      height: 3px;\n                      background: linear-gradient(90deg, transparent, ${notice.color}, transparent);\n                      margin: 1.5rem auto;\n                      width: 80%;\n                      opacity: 0.3;\n                  }\n                  \n                  .support-info {\n                      background: rgba(0,0,0,0.02);\n                      padding: 1rem;\n                      border-radius: 8px;\n                      margin: 1.5rem 0;\n                      border-left: 3px solid ${notice.color};\n                      text-align: left;\n                  }\n                  \n                  .support-link {\n                      color: ${notice.color};\n                      text-decoration: none;\n                      font-weight: 600;\n                      word-break: break-all;\n                      display: inline-block;\n                      margin-top: 0.3rem;\n                  }\n                  \n                  .client-info {\n                      font-size: 0.85rem;\n                      margin-top: 1rem;\n                      color: #666;\n                  }\n                  \n                  .icon {\n                      font-size: 1.3em;\n                  }\n                  \n                  @keyframes fadeIn {\n                      from { opacity: 0; transform: translateY(20px); }\n                      to { opacity: 1; transform: translateY(0); }\n                  }\n                  \n                  @media (max-width: 350px) {\n                      .license-notice {\n                          padding: 1.2rem;\n                          margin: 10px;\n                      }\n                      \n                      .notice-title {\n                          font-size: 1.2rem;\n                      }\n                  }\n              </style>\n              \n              <div class="license-notice">\n                  <h2 class="notice-title">\n                      <span class="icon">${notice.icon}</span>\n                      ${notice.title}\n                  </h2>\n                  \n                  <div class="notice-content">\n                      <p>${notice.message}</p>\n                  </div>\n                  \n                  ${type!=="deleted"?`\n                  <div class="divider"></div>\n                  \n                  <div class="support-info">\n                      <p style="margin:0 0 5px 0;font-weight:500;">${notice.contactLabel}</p>\n                      <a class="support-link" href="mailto:${clientEmail}">\n                          ${clientEmail}\n                      </a>\n                      ${clientPhone}\n                  </div>\n                  `:""}\n                  \n                  ${domainData?`\n                  <div class="client-info">\n                      <h4>${clientName}</h4>\n                  </div>\n                  `:""}\n              </div>\n          `;this.body.innerHTML="";this.body.className="license-notice-container";this.body.innerHTML=noticeHTML}displayBlankPage(){this.body.innerHTML="";this.body.style.backgroundColor="white";this.body.style.margin="0";this.body.style.padding="0";this.body.style.minHeight="100vh"}init(){this.handleLicenseStatus()}}new UbuntuDevSpace({}).init()}));